// simple reference matcher: does pattern (echo route syntax) match path?
func refMatch(pattern, path string) bool {
	if pattern == "" {
		pattern = "/"
	}
	if !strings.HasPrefix(pattern, "/") {
		pattern = "/" + pattern
	}
	// build regexp
	var b strings.Builder
	b.WriteString("^")
	i := 0
	for i < len(pattern) {
		ch := pattern[i]
		if ch == ':' {
			j := i + 1
			for j < len(pattern) && pattern[j] != '/' {
				j++
			}
			b.WriteString("[^/]+")
			i = j
		} else if ch == '*' {
			b.WriteString(".*")
			i++
		} else {
			b.WriteString(regexp.QuoteMeta(string(ch)))
			i++
		}
	}
	b.WriteString("$")
	re, err := regexp.Compile(b.String())
	if err != nil {
		return false
	}
	return re.MatchString(path)
}

type findResult struct {
	path   string
	params []string
	pnames []string
	panic  interface{}
	hung   bool
}

func runFind(t *testing.T, e *Echo, method, path string, timeout time.Duration) findResult {
	res := findResult{}
	done := make(chan findResult, 1)
	go func() {
		r := findResult{}
		defer func() {
			if rec := recover(); rec != nil {
				r.panic = rec
			}
			done <- r
		}()
		c := e.NewContext(nil, nil).(*context)
		e.router.Find(method, path, c)
		r.path = c.Path()
		r.pnames = append([]string{}, c.pnames...)
		r.params = append([]string{}, c.pvalues...)
	}()
	select {
	case r := <-done:
		return r
	case <-time.After(timeout):
		res.hung = true
		return res
	}
}

func buildEcho(routes []string) *Echo {
	e := New()
	for i, rp := range routes {
		m := http.MethodGet
		if i%3 == 1 {
			m = http.MethodPost
		}
		e.router.Add(m, rp, func(c Context) error { return nil })
	}
	return e
}

