func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := validHTTPScheme(c.request.Header.Get(HeaderXForwardedProto)); scheme != "" {
		return scheme
	}
	if scheme := validHTTPScheme(c.request.Header.Get(HeaderXForwardedProtocol)); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := validHTTPScheme(c.request.Header.Get(HeaderXUrlScheme)); scheme != "" {
		return scheme
	}
	return "http"
}

// validHTTPScheme returns the given scheme in lower case when it is a valid
// HTTP scheme, i.e. `http` or `https`. It returns an empty string otherwise so
// that invalid header values are ignored and the next source is considered.
func validHTTPScheme(scheme string) string {
	switch {
	case strings.EqualFold(scheme, "http"):
		return "http"
	case strings.EqualFold(scheme, "https"):
		return "https"
	}
	return ""
}

